import React, { useEffect, useState } from "react";
import { T, grid } from "../theme";
import { useNarrow } from "../hooks";
import { Btn, Empty, H1, Splash } from "../ui/primitives";
import { GameCard } from "./Browse";
import { TrailerHero } from "../ui/TrailerHero";
import { loadActiveTrailer } from "../lib/marketing";

export function Home({ games, saves, go }) {
  const narrow = useNarrow();
  const [trailer, setTrailer] = useState(null);

  const lastPlayedAt = {};
  for (const key of Object.keys(saves ?? {})) {
    const worldId = key.split(":")[0];
    const t = saves[key]?.updatedAt;
    if (t && (!lastPlayedAt[worldId] || t > lastPlayedAt[worldId]))
      lastPlayedAt[worldId] = t;
  }

  const recentlyPlayed = games
    .filter((g) => lastPlayedAt[g.id])
    .sort((a, b) => (lastPlayedAt[b.id] > lastPlayedAt[a.id] ? 1 : -1));

  const remaining = Math.max(0, 12 - recentlyPlayed.length);
  const newest = remaining > 0
    ? games
        .filter((g) => g.published && !lastPlayedAt[g.id])
        .sort((a, b) => (b.createdAt > a.createdAt ? 1 : -1))
        .slice(0, remaining)
    : [];

  const wantsTrailer = recentlyPlayed.length === 0 && !narrow;
  useEffect(() => {
    if (!wantsTrailer) return;
    loadActiveTrailer().then(setTrailer).catch(() => {});
  }, [wantsTrailer]);

  const resumeGame = !narrow && recentlyPlayed.length > 0 ? recentlyPlayed[0] : null;
  const openGame = (g, from) =>
    go("game", { id: g.id, authorUsername: g.authorUsername, slug: g.slug, from });

  return (
    <div className="pf-in">

      {resumeGame && (
        <div className="pf-card" onClick={() => openGame(resumeGame, "home")}
          style={{ display: "grid", gridTemplateColumns: "minmax(0,1.4fr) minmax(0,1fr)",
            gap: 24, marginBottom: 34, alignItems: "center" }}>
          <Splash seed={resumeGame.id} src={resumeGame.coverUrl} ratio={0.5625} />
          <div>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 8 }}>
              continue playing
            </div>
            <div className="pf-title"
              style={{ fontFamily: T.serif, fontSize: 30, lineHeight: 1.15, marginBottom: 8 }}>
              {resumeGame.title}
            </div>
            <p style={{ fontFamily: T.serif, fontSize: 16, lineHeight: 1.55,
              color: T.boneDim, margin: "0 0 14px" }}>
              {resumeGame.blurb}
            </p>
            <Btn kind="solid"
              onClick={(e) => { e.stopPropagation(); openGame(resumeGame, "home"); }}>
              Resume
            </Btn>
          </div>
        </div>
      )}

      {!resumeGame && trailer && (
        <TrailerHero trailer={trailer}>
          <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 8 }}>
            welcome
          </div>
          <div className="pf-title"
            style={{ fontFamily: T.serif, fontSize: 30, lineHeight: 1.15, marginBottom: 8 }}>
            Worlds you imagine, drawn for you.
          </div>
          <p style={{ fontFamily: T.serif, fontSize: 16, lineHeight: 1.55,
            color: T.boneDim, margin: "0 0 14px" }}>
            Pick something below to play, or describe a world of your own and watch it
            appear, room by room.
          </p>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <Btn kind="solid" onClick={() => go("browse")}>Find a game</Btn>
            <Btn onClick={() => go("create")}>Create a world</Btn>
          </div>
        </TrailerHero>
      )}

      <H1 sub={recentlyPlayed.length
        ? "Games you have recently played."
        : "Start anywhere — nothing here is locked."}>
        {recentlyPlayed.length ? "Recently played" : "New to Ascentery"}
      </H1>

      {recentlyPlayed.length > 0 && (
        <div style={{ marginBottom: 32 }}>
          <div style={grid}>
            {recentlyPlayed.map((g) => (
              <GameCard key={g.id} g={g} go={go} onClick={() => openGame(g, "home")} />
            ))}
          </div>
        </div>
      )}

      {newest.length > 0 && (
        <div>
          <div style={{ fontFamily: T.serif, fontSize: 19, marginBottom: 14 }}>
            {recentlyPlayed.length ? "Newest games" : "Start here"}
          </div>
          <div style={grid}>
            {newest.map((g) => (
              <GameCard key={g.id} g={g} go={go} onClick={() => openGame(g, "home")} />
            ))}
          </div>
        </div>
      )}

      {!recentlyPlayed.length && !newest.length && (
        <Empty title="Nothing here yet." line="Browse to find something to play." />
      )}
    </div>
  );
}
