import React, { useState, useEffect } from "react";
import {
  deleteWorld,
  generateCompleteWalkthrough,
  isFullyIllustrated,
  loadArt,
  loadWorldData,
  money,
  repairWorld,
  saveWorldData,
  saveWorldDetails,
  setPublished,
  syncArtEntries,
} from "../lib/db";
import { buildWalkthrough } from "../engine/engine";
import { ArtTab } from "./ArtTab";
import { T, inputStyle } from "../theme";
import { Btn, Chip, Empty, Field } from "../ui/primitives";
import { renderMarkdown } from "../ui/markdownLite";

export function EditGame({ game, refreshWorlds, me, setMe, go, chars, initialTab }) {
  const [tab, setTab] = useState(initialTab ?? "art");
  const [art, setArt] = useState(null);
  const [illustrated, setIllustrated] = useState(false);
  const [pubError, setPubError] = useState(null);
  const [deleteStage, setDeleteStage] = useState(0);      // 0 idle | 1 confirming | 2 typing the name
  const [deleteText, setDeleteText] = useState("");
  const [deleting, setDeleting] = useState(false);

  const checkIllustrated = () => {
    if (!game?.id) return;
    isFullyIllustrated(game.id).then(setIllustrated).catch(() => setIllustrated(false));
  };

  useEffect(() => {
    if (!game) return;
    let cancelled = false;
    loadArt(game.id)
      .then((rs) => { if (!cancelled) setArt(rs); })
      .catch(() => { if (!cancelled) setArt([]); });
    checkIllustrated();
    return () => { cancelled = true; };
  }, [game?.id]);

  if (!game) return <Empty title="Not found." line="This world may have been deleted." />;
  if (game.authorId !== me?.id && !me?.isAdmin) {
    return <Empty title="Not your world." line="You can only edit worlds you created." />;
  }

  return (
    <div className="pf-in">
      <Btn kind="ghost" onClick={() => go("game", { id: game.id, from: "mine" })}
        style={{ marginBottom: 14 }}>back</Btn>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 4, flexWrap: "wrap" }}>
        <h1 style={{ fontFamily: T.serif, fontSize: 28, fontWeight: 400, margin: 0 }}>{game.title}</h1>
        <Chip status={game.status} published={game.published} />
      </div>
      <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 18 }}>
        {game.rooms} rooms &middot; {game.mobs} characters &middot; {game.plays.toLocaleString()} plays
      </div>

      {game.status === "ready" && (
        <div style={{ marginBottom: 22, display: "flex", alignItems: "center", gap: 10 }}>
          <Btn kind="solid" disabled={!chars?.length}
            onClick={() => go("play", { id: game.id, charId: chars?.[0]?.id, authorUsername: game.authorUsername, slug: game.slug })}>
            Play
          </Btn>
          {!chars?.length && (
            <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              Make a character on your profile first.
            </span>
          )}
          <Btn kind={game.published ? "ghost" : (illustrated ? "solid" : "quiet")}
            disabled={!game.published && !illustrated}
            style={{ marginLeft: "auto", ...(game.published ? { borderColor: T.moss, color: T.moss } : {}) }}
            onClick={async () => {
              setPubError(null);
              try {
                await setPublished(game.id, !game.published);
                await refreshWorlds();
              } catch (e) {
                if (e.needsUsername) go("username", { reason: "publish", next: "mine" });
                else setPubError(e.message);
              }
            }}>
            {game.published ? "Unpublish" : "Publish"}
          </Btn>
        </div>
      )}

      {game.status === "failed" && (
        <div style={{ marginBottom: 22 }}>
          {game.failureNote && (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7,
              border: "1px solid " + T.clay + "44", padding: 14, borderRadius: 2, marginBottom: 14 }}>
              {game.failureNote}
            </p>
          )}
          <Btn kind="solid" onClick={() => go("create", { resumeId: game.id })}>
            Try building the world again
          </Btn>
        </div>
      )}

      <div style={{ display: "flex", gap: 4, borderBottom: "1px solid " + T.edge, marginBottom: 24, flexWrap: "wrap" }}>
        {[["details", "Details"], ["art", "Pictures"], ["walkthrough", "Walkthrough"], ["repair", "Changes / Repairs"], ["settings", "Settings"]].map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} className="pf-btn"
            style={{ background: "none", border: "none", cursor: "pointer", padding: "10px 14px", fontFamily: T.mono, fontSize: 12,
              color: tab === k ? T.bone : T.boneDim, boxShadow: tab === k ? "inset 0 -2px 0 " + T.ochre : "none" }}>
            {label}
          </button>
        ))}
      </div>

      {tab === "art" && (
        art === null
          ? <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
          : <>
              {art.length
                ? <ArtTab entries={art} setEntries={setArt} me={me} setMe={setMe} worldId={game.id} onDrawn={checkIllustrated} title={game.title} />
                : <Empty title="Nothing to draw yet." line="Pictures appear once the world has been built." />
              }
            </>
      )}

      {tab === "details" && <DetailsTab game={game} refreshWorlds={refreshWorlds} />}

      {tab === "walkthrough" && (
        game.status === "ready"
          ? <WalkthroughTab worldId={game.id} me={me} setMe={setMe} go={go} />
          : <Empty title="Nothing to walk through yet." line="This world has not finished building." />
      )}

      {tab === "repair" && (
        game.status === "ready"
          ? <RepairTab worldId={game.id} title={game.title} isAdmin={me?.isAdmin} onJsonSaved={async () => {
              try {
                const added = await syncArtEntries(game.id);
                if (added > 0) {
                  const fresh = await loadArt(game.id);
                  setArt(fresh);
                }
              } catch {
                // sync failures are silent — the user saved the JSON successfully
              }
            }} />
          : <Empty title="Nothing to repair yet." line="This world has not finished building." />
      )}

      {tab === "settings" && (
        <div style={{ maxWidth: 480 }}>
          <Field label="Published"
            hint={game.published
              ? "Unpublishing hides it from Browse. People mid-playthrough keep their saves."
              : illustrated
                ? "Every picture is drawn. Ready when you are."
                : "A world can be published once every room, character, item and prop has a picture. Check the Pictures tab."}>
            <Btn disabled={game.status !== "ready" || (!game.published && !illustrated)}
              onClick={async () => {
                setPubError(null);
                try {
                  await setPublished(game.id, !game.published);
                  await refreshWorlds();
                } catch (e) {
                  if (e.needsUsername) go("username", { reason: "publish", next: "mine" });
                  else setPubError(e.message);
                }
              }}>
              {game.published ? "Unpublish" : "Publish"}
            </Btn>
          </Field>
          {pubError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: -8, marginBottom: 18 }}>
              {pubError}
            </p>
          )}
          <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 20, marginTop: 20 }}>
            {deleteStage === 0 && (
              <Btn kind="danger" onClick={() => setDeleteStage(1)}>
                Delete this world
              </Btn>
            )}

            {deleteStage === 1 && (
              <div>
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7, margin: "0 0 12px" }}>
                  This deletes "{game.title}" — every room, character, item, picture, and anyone's
                  save — for good. Are you sure?
                </p>
                <div style={{ display: "flex", gap: 10 }}>
                  <Btn kind="danger" onClick={() => setDeleteStage(2)}>Yes, delete it</Btn>
                  <Btn kind="ghost" onClick={() => setDeleteStage(0)}>Never mind</Btn>
                </div>
              </div>
            )}

            {deleteStage === 2 && (
              <div>
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7, margin: "0 0 12px" }}>
                  Type the world's exact title to confirm — "{game.title}".
                </p>
                <input value={deleteText} onChange={(e) => setDeleteText(e.target.value)}
                  placeholder={game.title}
                  style={{ ...inputStyle, marginBottom: 12 }} />
                <div style={{ display: "flex", gap: 10 }}>
                  <Btn kind="danger" disabled={deleting || deleteText !== game.title}
                    onClick={async () => {
                      setDeleting(true);
                      try { await deleteWorld(game.id); await refreshWorlds(); go("mine"); }
                      catch (e) { console.error(e); setDeleting(false); }
                    }}>
                    {deleting ? "deleting…" : "Delete forever"}
                  </Btn>
                  <Btn kind="ghost" onClick={() => { setDeleteStage(0); setDeleteText(""); }}>Cancel</Btn>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export function DetailsTab({ game, refreshWorlds }) {
  const [title, setTitle] = useState(game.title);
  const [brief, setBrief] = useState(game.brief ?? "");
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState(null);

  const save = async (patch) => {
    setError(null);
    try {
      await saveWorldDetails(game.id, patch);
      await refreshWorlds();
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div style={{ maxWidth: 560 }}>
      <Field label="Title" hint="Shown on the catalog card and used to build the splash screen.">
        <input value={title} onChange={(e) => setTitle(e.target.value)}
          onBlur={() => save({ title })} style={inputStyle} />
      </Field>

      {/* The next three follow the Create wizard's own order — what was
          typed, what it became, what it became again — so reading down
          the page traces the same path building the world once did.
          Only the last one is still live; the first two are a historical
          record, kept purely so the story, goals, and tone don't get
          lost once the wizard that produced them is gone. Neither is
          shown at all for a world built before this was tracked. */}
      {game.gameBrief && (
        <Field label="The Game Brief" hint="What was originally typed into the first step of the Create wizard.">
          <textarea value={game.gameBrief} readOnly rows={6}
            style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical", opacity: 0.75, cursor: "default" }} />
        </Field>
      )}

      {game.storyDetails && (
        <Field label="The Story Details" hint="What the brief above became after the wizard's second step expanded it.">
          <textarea value={game.storyDetails} readOnly rows={8}
            style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical", opacity: 0.75, cursor: "default" }} />
        </Field>
      )}

      <Field label="The Game Details" hint="What actually went on to build the world. This is not shown to players, but it is what an amendment or repair reads for context.">
        <textarea value={brief} onChange={(e) => setBrief(e.target.value)}
          onBlur={() => save({ brief })} rows={10}
          style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical" }} />
      </Field>

      <div style={{ fontFamily: T.mono, fontSize: 11, color: saved ? T.moss : T.clay, minHeight: 16 }}>
        {saved ? "saved" : error || " "}
      </div>
    </div>
  );
}

function WalkthroughTab({ worldId, me, setMe, go }) {
  const [world, setWorld] = useState(null);
  const [completeText, setCompleteText] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("compact");
  const [genBusy, setGenBusy] = useState(false);
  const [genError, setGenError] = useState(null);
  const [needsFunds, setNeedsFunds] = useState(false);
  const [copied, setCopied] = useState(false);
  const [regenBusy, setRegenBusy] = useState(false);
  const [regenError, setRegenError] = useState(null);
  const [regenKey, setRegenKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    loadWorldData(worldId)
      .then((d) => { if (!cancelled) { setWorld(d.data); setCompleteText(d.complete_walkthrough ?? null); } })
      .catch((e) => { if (!cancelled) setError(e.message); });
    return () => { cancelled = true; };
  }, [worldId]);

  const regenCompact = async () => {
    setRegenBusy(true); setRegenError(null);
    try {
      const d = await loadWorldData(worldId);
      setWorld(d.data);
      setRegenKey((k) => k + 1);
    } catch (e) {
      setRegenError(e.message);
    } finally {
      setRegenBusy(false);
    }
  };

  const generate = async () => {
    setGenBusy(true); setGenError(null); setNeedsFunds(false);
    try {
      const { text, balance_cents } = await generateCompleteWalkthrough(worldId);
      setCompleteText(text);
      if (typeof balance_cents === "number") setMe((m) => ({ ...m, balance: balance_cents }));
    } catch (e) {
      setGenError(e.message);
      setNeedsFunds(Boolean(e.needsFunds));
    } finally {
      setGenBusy(false);
    }
  };

  // Same fallback reasoning as copyJson in the Repair tab below: the
  // modern clipboard API is not universally available (older Safari,
  // some embedded webviews), and fails silently rather than throwing
  // something visible, so a classic textarea + execCommand fallback
  // covers far more of those cases.
  const copyWalkthrough = async () => {
    if (!completeText) return;
    try {
      await navigator.clipboard.writeText(completeText);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
      return;
    } catch { /* fall through to the classic approach below */ }

    try {
      const ta = document.createElement("textarea");
      ta.value = completeText;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      if (!ok) throw new Error("execCommand copy returned false");
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setGenError("Could not copy — your browser may be blocking clipboard access. Select the text above and copy it manually.");
    }
  };

  if (error) {
    return <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay }}>{error}</p>;
  }
  if (!world) {
    return <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>;
  }

  const modeToggle = (
    <div style={{ display: "flex", gap: 6, marginBottom: 20 }}>
      {[["compact", "Compact Walkthrough"], ["complete", "Complete Walkthrough"]].map(([k, label]) => (
        <button key={k} onClick={() => setMode(k)} className="pf-btn"
          style={{ padding: "8px 14px", borderRadius: 2, cursor: "pointer", background: "transparent",
            fontFamily: T.mono, fontSize: 12, color: mode === k ? T.bone : T.boneDim,
            border: "1px solid " + (mode === k ? T.ochre : T.edge) }}>
          {label}
        </button>
      ))}
    </div>
  );

  if (mode === "complete") {
    return (
      <div style={{ maxWidth: 720 }}>
        {modeToggle}
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
          Written by a model, grounded in this world's actual rooms, characters, items, and quest
          stages — a narrative guide rather than a plain step list. Costs {money(8)} to write or rewrite,
          and is saved, not regenerated every time you open this tab.
        </p>

        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
          <Btn kind="solid" disabled={genBusy} onClick={generate}>
            {genBusy ? "writing…" : completeText ? `Rewrite · ${money(8)}` : `Write it · ${money(8)}`}
          </Btn>
          {completeText && (
            <Btn kind="ghost" style={{ marginLeft: "auto" }} onClick={copyWalkthrough}>
              {copied ? "Copied" : "Copy to clipboard"}
            </Btn>
          )}
        </div>

        {genError && (
          <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 16 }}>
            {genError}
            {needsFunds && <Btn kind="ghost" style={{ marginLeft: 10 }} onClick={() => go("creator")}>Add funds</Btn>}
          </p>
        )}

        {completeText ? (
          <div style={{ background: T.raised, border: "1px solid " + T.edge, borderRadius: 4, padding: "8px 24px" }}>
            {renderMarkdown(completeText, {
              h1: { fontFamily: T.serif, fontSize: 24, color: T.bone, margin: "20px 0 10px" },
              h2: { fontFamily: T.serif, fontSize: 19, color: T.bone, margin: "18px 0 8px" },
              h3: { fontFamily: T.serif, fontSize: 16, color: T.ochre, margin: "14px 0 6px" },
              p: { fontFamily: T.serif, fontSize: 14.5, lineHeight: 1.7, color: T.bone, margin: "0 0 12px" },
              list: { margin: "0 0 14px", paddingLeft: 22 },
              listItem: { fontFamily: T.serif, fontSize: 14.5, lineHeight: 1.7, color: T.bone, marginBottom: 4 },
              blockquote: { fontFamily: T.serif, fontStyle: "italic", fontSize: 14.5, lineHeight: 1.7,
                color: T.boneDim, borderLeft: "3px solid " + T.edge, margin: "0 0 14px", padding: "2px 16px" },
              hr: { border: "none", borderTop: "1px solid " + T.edge, margin: "20px 0" },
              code: { fontFamily: T.mono, fontSize: 12.5, lineHeight: 1.5, color: T.boneDim,
                background: T.ground, border: "1px solid " + T.edge, borderRadius: 4,
                padding: "14px 16px", margin: "0 0 16px", overflowX: "auto", whiteSpace: "pre" },
              table: { fontFamily: T.mono, fontSize: 12 },
              th: { textAlign: "left", padding: "6px 10px", borderBottom: "1px solid " + T.ochre, color: T.ochre },
              td: { padding: "6px 10px", borderBottom: "1px solid " + T.edge, color: T.bone },
            })}
          </div>
        ) : !genBusy && (
          <Empty title="No complete walkthrough yet." line="Write one above to see it here." />
        )}
      </div>
    );
  }

  const steps = buildWalkthrough(world);
  if (!steps.length) {
    return (<div>{modeToggle}<Empty title="No quests in this world." line="There is nothing to walk through yet." /></div>);
  }

  const DIR_ARROW = { north: "↑", south: "↓", east: "→", west: "←", up: "↗", down: "↙" };

  return (
    <div style={{ maxWidth: 640 }}>
      {modeToggle}
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
        Computed directly from the world itself, the same way the reachability check is — not
        written by a model, so it cannot describe a step that does not actually work. If the world
        changes, so does this.
      </p>

      {steps.map((s, i) => (
        <div key={i} style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: "12px 16px", marginBottom: 10 }}>
          <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.ochre, marginBottom: 4 }}>
            {s.quest}
          </div>
          <div style={{ fontFamily: T.serif, fontSize: 15.5, marginBottom: 8 }}>
            {i + 1}. {s.goal}
          </div>

          {s.already ? (
            <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim }}>
              {"already true — "}{s.action}
            </div>
          ) : s.note ? (
            <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay }}>{s.note}</div>
          ) : (
            <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, lineHeight: 1.9 }}>
              <div>{"📍 "}{s.roomName}</div>
              <div>
                {"🚶 "}{s.path.length
                  ? s.path.map((d) => `${DIR_ARROW[d] ?? d} ${d}`).join("  ")
                  : "already there"}
              </div>
              <div>{"⚡ "}{s.action}</div>
            </div>
          )}
        </div>
      ))}

      {me?.isAdmin && (
        <div style={{ marginTop: 18, paddingTop: 18, borderTop: "1px solid " + T.edge }}>
          <Btn kind="ghost" disabled={regenBusy} onClick={regenCompact}>
            {regenBusy ? "reloading…" : "Recompute walkthrough"}
          </Btn>
          {regenError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 8 }}>
              {regenError}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

function RepairTab({ worldId, title, isAdmin, onJsonSaved }) {
  const [world, setWorld] = useState(null);
  const [loadError, setLoadError] = useState(null);
  const [query, setQuery] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [needsFunds, setNeedsFunds] = useState(false);
  const [result, setResult] = useState(null);       // { status, reply, cost_cents }
  const [copied, setCopied] = useState(false);
  const [checkWalkthrough, setCheckWalkthrough] = useState(false);
  const [jsonDraft, setJsonDraft] = useState(null);   // editable text in the JSON box
  const [jsonSaving, setJsonSaving] = useState(false);
  const [jsonSaveError, setJsonSaveError] = useState(null);
  const [jsonSaved, setJsonSaved] = useState(false);

  const refresh = () => {
    loadWorldData(worldId)
      .then(({ data }) => { setWorld(data); setJsonDraft(JSON.stringify(data, null, 2)); })
      .catch((e) => setLoadError(e.message));
  };
  useEffect(() => { refresh(); }, [worldId]);

  const send = async () => {
    if (!query.trim() || busy) return;
    setBusy(true); setError(null); setNeedsFunds(false); setCheckWalkthrough(false);
    try {
      const res = await repairWorld(worldId, query.trim());
      setResult(res);
      setWorld(res.world);
      setQuery("");
    } catch (e) {
      setError(e.message);
      setNeedsFunds(Boolean(e.needsFunds));
    } finally {
      setBusy(false);
    }
  };

  const copyJson = async () => {
    const text = JSON.stringify(world, null, 2);
    // The modern clipboard API is not universally available — older
    // Safari and some embedded webviews either lack it or reject it
    // depending on permissions, and fail silently rather than throwing
    // something visible. A classic textarea + execCommand fallback covers
    // far more of those cases, so this only reports failure if both fail.
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
      return;
    } catch { /* fall through to the classic approach below */ }

    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      if (!ok) throw new Error("execCommand copy returned false");
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setError("Could not copy — your browser may be blocking clipboard access. Select the text in the box above and copy it manually.");
    }
  };

  const saveJson = async () => {
    setJsonSaveError(null);
    let parsed;
    try {
      parsed = JSON.parse(jsonDraft);
    } catch (e) {
      setJsonSaveError(`Invalid JSON: ${e.message}`);
      return;
    }
    setJsonSaving(true);
    try {
      await saveWorldData(worldId, parsed);
      setWorld(parsed);
      setJsonSaved(true);
      setTimeout(() => setJsonSaved(false), 2000);
      onJsonSaved?.();
    } catch (e) {
      setJsonSaveError(e.message);
    } finally {
      setJsonSaving(false);
    }
  };

  const walkthrough = checkWalkthrough && world ? buildWalkthrough(world) : null;

  return (
    <div style={{ maxWidth: 720 }}>
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
        Describe a bug to fix, or a change you want made on purpose — "once inside the room there
        is no exit and the door is locked," or "swap the flute puzzle for a rubber-mouse decoy."
        The model reads the whole world and makes the change, but nothing is ever applied unless it
        passes the same check every generated world already has to pass, so a change that breaks
        something else is refused rather than saved. Costs {money(10)} whether or not anything
        actually changes, since the attempt happens either way. Every change here is undoable from
        the World tab, the same as any other amendment.
      </p>

      {isAdmin && (
        <div style={{ marginBottom: 24 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              World JSON (admin only)
            </div>
            <Btn kind="ghost" onClick={copyJson} disabled={!world}>
              {copied ? "copied" : "copy"}
            </Btn>
            <Btn kind="ghost" disabled={jsonSaving || !world || jsonDraft === JSON.stringify(world, null, 2)} onClick={saveJson}>
              {jsonSaving ? "saving…" : jsonSaved ? "saved" : "save changes"}
            </Btn>
          </div>
          {loadError ? (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay }}>{loadError}</p>
          ) : (
            <textarea
              value={jsonDraft ?? (world ? JSON.stringify(world, null, 2) : "loading…")}
              onChange={(e) => { setJsonDraft(e.target.value); setJsonSaveError(null); }}
              rows={18}
              spellCheck={false}
              style={{ ...inputStyle, fontFamily: T.mono, fontSize: 11, lineHeight: 1.5, resize: "vertical" }}
            />
          )}
          {jsonSaveError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 6 }}>
              {jsonSaveError}
            </p>
          )}
        </div>
      )}

      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18, marginBottom: 18 }}>
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 8 }}>
          Response
        </div>
        {result ? (
          <div style={{ border: "1px solid " + (result.status === "modified" ? T.moss : T.edge) + "88",
            borderRadius: 2, padding: "12px 14px" }}>
            <div style={{ fontFamily: T.mono, fontSize: 10.5, color: result.status === "modified" ? T.moss : T.boneDim,
              marginBottom: 8 }}>
              {result.status === "modified" ? "repaired — the world was changed" : "unchanged"}
            </div>
            <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, margin: 0 }}>{result.reply}</p>

            {isAdmin && result.rejected_proposal && (
              <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid " + T.edge }}>
                <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.ochre, marginBottom: 8 }}>
                  Admin only — what was proposed and rejected
                </div>
                <pre style={{ maxHeight: 320, overflow: "auto", margin: 0, padding: 10,
                  background: T.ground, border: "1px solid " + T.edge, borderRadius: 2,
                  fontFamily: T.mono, fontSize: 10.5, lineHeight: 1.5, color: T.boneDim,
                  whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
                  {JSON.stringify(result.rejected_proposal, null, 2)}
                </pre>
              </div>
            )}
          </div>
        ) : (
          <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing asked yet.</p>
        )}
      </div>

      {result && (
        <div style={{ marginBottom: 18 }}>
          {!checkWalkthrough ? (
            <Btn kind="ghost" onClick={() => setCheckWalkthrough(true)}>
              Check the walkthrough
            </Btn>
          ) : (
            <>
              <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, lineHeight: 1.7, margin: "0 0 12px" }}>
                Computed directly from the world as it stands right now — not a second AI call,
                which could describe a step that does not actually work. This is the same
                deterministic check the Walkthrough tab uses, so if it completes cleanly here, the
                problem is genuinely solved.
              </p>
              {walkthrough && !walkthrough.length && (
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No quests in this world.</p>
              )}
              {walkthrough && walkthrough.map((s, i) => (
                <div key={i} style={{ fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.9, color: T.boneDim,
                  borderBottom: "1px solid " + T.edge + "55", padding: "6px 0" }}>
                  <span style={{ color: s.note ? T.clay : T.boneDim }}>{i + 1}. {s.goal}</span>
                  {s.note && <span style={{ color: T.clay }}> — {s.note}</span>}
                </div>
              ))}
            </>
          )}
        </div>
      )}

      <Field label="What you want changed">
        <textarea value={query} onChange={(e) => setQuery(e.target.value)} rows={4}
          placeholder="Once inside the room there is no exit and the door is locked. Or: instead of the flute, let the player find a rubber mouse to distract the cat with."
          style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical" }} />
      </Field>

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "-8px 0 14px" }}>
          {error}
          {needsFunds && <Btn kind="ghost" style={{ marginLeft: 10 }}>Add funds</Btn>}
        </p>
      )}

      <Btn kind="solid" disabled={busy || !query.trim()} onClick={send}>
        {busy ? "looking…" : `Ask · ${money(10)}`}
      </Btn>
    </div>
  );
}
